select customer_id, plan, case when monthly_fee >= 216 then 'high' when monthly_fee >= 40 then 'mid' else 'low' end as monthly_fee_bucket, avg(monthly_fee) as avg_monthly_fee, count(case when plan = 'premium' then 1 end) as premium_count, count(*) as cnt from subscriptions where month(end_date) in (1, 8, 10) and customer_id in (1, 12) group by customer_id, plan, monthly_fee_bucket order by premium_count desc;
